//根据Cookie获取用户登录信息
var jieqiUserView = {
  jieqiUserId: 0,
  jieqiUserName: '',
  jieqiUserPassword: '',
  jieqiUserToken: '',
  jieqiUserGroup: 0,
  jieqiUserHonorId: 0,
  jieqiNewMessage: 0,
  jieqiCodeLogin: 0,
  jieqiCodePost: 0
};
if (document.cookie.indexOf('jieqiUserView') >= 0) {
  var cinfo = Cookie.get('jieqiUserView');
  start = 0;
  offset = cinfo.indexOf(',', start);
  while (offset > 0) {
	tmpval = cinfo.substring(start, offset);
	tmpidx = tmpval.indexOf('=');
	if (tmpidx > 0) {
	  tmpname = tmpval.substring(0, tmpidx);
	  tmpval = tmpval.substring(tmpidx + 1, tmpval.length);
	  if (jieqiUserView.hasOwnProperty(tmpname)) jieqiUserView[tmpname] = tmpval;
	}
	start = offset + 1;
	if (offset < cinfo.length) {
	  offset = cinfo.indexOf(',', start);
	  if (offset == -1) offset = cinfo.length;
	} else {
	  offset = -1;
	}
  }
}

var maxWidth = 760;

